import json, random, subprocess, itertools
from fractions import Fraction

RUN=['/app/submission/run.sh']

def ctxs(req, part):
    K=req['window']; out=[]
    for tr in req[part]:
        rows=sorted(tr['rows'],key=lambda r:r['t'])
        for s in range(len(rows)-K+1):
            out.append((tr,s,rows[s:s+K]))
    return out

def term(t, rows, dollar, fields):
    if 'field' in t:
        at=dollar if t['at']=='$' else t['at']
        return rows[at]['values'][fields[t['field']]]
    if 'const' in t:return t['const']
    if 'scale' in t:return t['scale']*term(t['term'],rows,dollar,fields)
    if 'add' in t:return term(t['add'][0],rows,dollar,fields)+term(t['add'][1],rows,dollar,fields)
    vals=[rows[i]['values'][fields[t['field']]] for i in range(t['from'],t['to']+1)]
    if t['aggregate']=='sum':return sum(vals)
    if t['aggregate']=='mean':return Fraction(sum(vals),len(vals))
    if t['aggregate']=='min':return min(vals)
    return max(vals)

def comp(c,rows,dollar,fields):
    a=term(c['left'],rows,dollar,fields);b=term(c['right'],rows,dollar,fields);op=c['cmp']
    return {'eq':a==b,'ne':a!=b,'lt':a<b,'le':a<=b,'gt':a>b,'ge':a>=b}[op]

def atom(a,rows,fields):
    if 'cmp' in a:return comp(a,rows,0,fields)
    vals=[comp(a['predicate'],rows,d,fields) for d in range(a['from'],a['to']+1)]
    return any(vals) if a['quantifier']=='any' else all(vals)

def reference(req):
    fields={f['name']:i for i,f in enumerate(req['schema'])}
    parts={p:ctxs(req,p) for p in ('train','probes','queries')}
    vals={p:[[atom(a,c[2],fields) for c in cs] for a in req['atoms']] for p,cs in parts.items()}
    n=len(req['atoms']); nt=len(parts['train']); np=len(parts['probes']); nq=len(parts['queries'])
    sources=list(dict.fromkeys(t['source'] for t in req['train']))
    sm={s:[i for i,c in enumerate(parts['train']) if c[0]['source']==s] for s in sources}
    eligible=[]
    if sources and np:
      for w in range(1,req['policy']['max_width']+1):
       for inds in itertools.combinations(range(n),w):
        for signs in itertools.product((False,True),repeat=w):
         lits=list(zip(inds,signs))
         lv=[[vals['train'][a][i] != neg for i in range(nt)] for a,neg in lits]
         if any(sum(v[i] for i in sm[s])<req['policy']['min_support'] for v in lv for s in sources):continue
         if not all(any(v[i] for v in lv) for i in range(nt)):continue
         ok=True
         for j,v in enumerate(lv):
          essential=[v[i] and not any(lv[z][i] for z in range(w) if z!=j) for i in range(nt)]
          if any(sum(essential[i] for i in sm[s])<req['policy']['min_witness'] for s in sources):ok=False;break
         if not ok:continue
         pv=[any(vals['probes'][a][i] != neg for a,neg in lits) for i in range(np)]
         if all(pv):continue
         sig=sum((1<<i) for i,v in enumerate(pv) if v)
         qv=[any(vals['queries'][a][i] != neg for a,neg in lits) for i in range(nq)]
         eligible.append((lits,sig,qv))
    classes={}
    for lits,sig,qv in eligible:
      classes.setdefault(sig,[]).append((lits,qv))
    queries=[]
    for qi,c in enumerate(parts['queries']):
      must=sum(all(not qv[qi] for _,qv in mem) for mem in classes.values())
      may=sum(any(not qv[qi] for _,qv in mem) for mem in classes.values())
      queries.append({'trace':c[0]['id'],'end':c[2][-1]['t'],'must':must,'may':may,'status':'violating' if must else 'ambiguous' if may else 'consistent'})
    return classes,queries,eligible

def gen_req(rng):
    K=rng.randint(1,3)
    schema=[{'name':'x','type':'SIZE','min':-3,'max':5},{'name':'y','type':'SIZE','min':-3,'max':5},{'name':'f','type':'FLAG'},{'name':'id','type':'ID','values':['a','b']}]
    def numterm(depth=0,quant=False):
      choices=['field','const']+(['agg'] if depth<2 else [])+(['scale','add'] if depth<1 else [])
      typ=rng.choice(choices)
      if typ=='field':return {'field':rng.choice(['x','y']),'at':('$' if quant and rng.random()<.5 else rng.randrange(K))}
      if typ=='const':return {'const':rng.randint(-3,5),'type':'SIZE'}
      if typ=='agg':return {'aggregate':rng.choice(['sum','mean','min','max']),'field':rng.choice(['x','y']),'from':0,'to':rng.randrange(K)}
      if typ=='scale':return {'scale':rng.choice([-2,-1,0,2]),'term':numterm(depth+1,quant)}
      return {'add':[numterm(depth+1,quant),numterm(depth+1,quant)]}
    def mkatom():
      quant=rng.random()<.45
      if rng.random()<.25:
       field=rng.choice(['f','id']); val=True if field=='f' else rng.choice(['a','b','c']); typ='FLAG' if field=='f' else 'ID'
       c={'cmp':rng.choice(['eq','ne']),'left':{'field':field,'at':('$' if quant else rng.randrange(K))},'right':{'const':val,'type':typ}}
      else:
       c={'cmp':rng.choice(['eq','ne','lt','le','gt','ge']),'left':numterm(quant=quant),'right':numterm(quant=quant)}
      if quant:return {'quantifier':rng.choice(['any','all']),'from':0,'to':rng.randrange(K),'predicate':c}
      return c
    atoms=[mkatom() for _ in range(rng.randint(1,6))]
    # Ensure generated nonquantified terms never contain $ (mkatom controls quant globally).
    def traces(part,count):
      out=[]
      for z in range(count):
       rows=[]
       for j in range(rng.randint(0,5)):
        rows.append({'t':rng.randint(-2,2)*10+j,'values':[rng.randint(-3,5),rng.randint(-3,5),rng.choice([True,False]),rng.choice(['a','b'])]})
       out.append({'id':part+str(z),'source':'s'+str(z%2),'rows':rows})
      return out
    return {'version':1,'schema':schema,'window':K,'atoms':atoms,'policy':{'max_width':rng.randint(1,3),'min_support':rng.randint(1,2),'min_witness':rng.randint(1,2)},'train':traces('tr',rng.randint(0,3)),'probes':traces('pr',rng.randint(0,2)),'queries':traces('qu',rng.randint(0,2))}

rng=random.Random(781236)
for case in range(350):
    req=gen_req(rng)
    p=subprocess.run(RUN,input=json.dumps(req).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=10)
    try: got=json.loads(p.stdout)
    except: print('BAD OUTPUT',case,p.stdout,p.stderr,json.dumps(req));raise
    if 'error' in got:
      print('UNEXPECTED ERROR',case,got,json.dumps(req));break
    classes,queries,eligible=reference(req)
    gotclasses={int(c['signature'],16):c for c in got['classes']}
    if set(gotclasses)!=set(classes) or any(gotclasses[s]['members']!=len(m) for s,m in classes.items()) or got['queries']!=queries:
      print('MISMATCH',case,json.dumps(req),json.dumps(got), 'REF',classes,queries,eligible);break
    # Check each emitted representative is actually a member of its class.
    elig_by_sig={s:{tuple(l) for l,_ in mem} for s,mem in classes.items()}
    for s,c in gotclasses.items():
      rep=tuple((l['atom'],l['negated']) for l in c['representative']['or'])
      if rep not in elig_by_sig[s]:print('BAD REP',case,s,rep,elig_by_sig[s]);raise SystemExit
else:
    print('350 randomized cases matched naive reference')
