import json,subprocess,copy,sys
RUN=['/app/submission/run.sh']
base=json.load(open('/app/examples/empty.json'))

def runraw(data):
 p=subprocess.run(RUN,input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=20)
 if p.returncode!=0:raise AssertionError((p.returncode,p.stderr))
 return json.loads(p.stdout)
def run(req):return runraw(json.dumps(req,separators=(',',':')).encode())
def expect(req,error='E_SCHEMA'):
 got=run(req)
 assert got=={'error':error},(got,req)
def mutate(path,value):
 r=copy.deepcopy(base);x=r
 for p in path[:-1]:x=x[p]
 x[path[-1]]=value;return r
# JSON-level classification.
for raw in [b'',b' ',b'{',b'{} trailing',b'\xef\xbb\xbf{}',b'\xff',b'{"a":1,"a":2}',b'NaN',b'{"x":Infinity}',b'[1,]',b'\x00']:
 assert runraw(raw)=={'error':'E_JSON'},raw
assert runraw(b'['*65+b'0'+b']'*65)=={'error':'E_JSON'}
assert runraw(b'['*64+b'0'+b']'*64)=={'error':'E_SCHEMA'}
assert runraw(b'{"x":1e999999999999999999999999}')=={'error':'E_SCHEMA'}
assert runraw(b'{"x":'+b'9'*5000+b'}')=={'error':'E_SCHEMA'}
# Exact keys / scalar types.
for key in list(base):expect(mutate([key],None) if key!='version' else mutate(['version'],2))
r=copy.deepcopy(base);r['extra']=1;expect(r)
for value in [True,1.0,'1',None,0,2,-1]:expect(mutate(['version'],value))
for value in [True,0,9,1.0,'1',None]:expect(mutate(['window'],value))
for key,val in [('max_width',0),('max_width',5),('max_width',True),('min_support',0),('min_support',4097),('min_witness',0),('min_witness',1.0)]:expect(mutate(['policy',key],val))
r=copy.deepcopy(base);r['policy']['x']=1;expect(r)
